const express = require('express');
const bcrypt = require('bcrypt');
const crypto = require('crypto');
const { Pool } = require('pg');

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: { rejectUnauthorized: true },
  max: 20
});

const sessions = new Map();

const SALT_ROUNDS = 12;
const SESSION_TTL = 3600000;
const MAX_USERNAME_LEN = 64;
const MAX_PASSWORD_LEN = 128;

// Security: strict username validation
function isValidUsername(username) {
  if (typeof username !== 'string') return false;
  if (username.length === 0 || username.length > MAX_USERNAME_LEN) return false;
  // Allow Unicode letters, digits, hyphens, underscores
  return /^[\p{L}\p{N}_-]+$/u.test(username);
}

function isValidPassword(password) {
  if (typeof password !== 'string') return false;
  if (password.length < 8 || password.length > MAX_PASSWORD_LEN) return false;
  return true;
}

// Security: constant-time session token generation
function generateSessionToken() {
  return crypto.randomBytes(32).toString('hex');
}

// Security: session cleanup to prevent memory exhaustion
setInterval(() => {
  const now = Date.now();
  for (const [token, session] of sessions.entries()) {
    if (now - session.createdAt > SESSION_TTL) {
      sessions.delete(token);
    }
  }
}, 60000);

// Middleware: rate limiting per IP
const loginAttempts = new Map();
const RATE_LIMIT_WINDOW = 900000; // 15 min
const MAX_ATTEMPTS = 5;

function rateLimitMiddleware(req, res, next) {
  const ip = req.ip;
  const now = Date.now();
  const attempts = loginAttempts.get(ip) || [];
  const recentAttempts = attempts.filter(t => now - t < RATE_LIMIT_WINDOW);
  if (recentAttempts.length >= MAX_ATTEMPTS) {
    return res.status(429).json({ error: 'Too many attempts. Try again later.' });
  }
  loginAttempts.set(ip, recentAttempts);
  next();
}

// Registration endpoint
app.post('/api/register', rateLimitMiddleware, async (req, res) => {
  try {
    const { username, password } = req.body;

    if (!isValidUsername(username) || !isValidPassword(password)) {
      return res.status(400).json({ error: 'Invalid input' });
    }

    // Normalize username for storage
    const normalizedUsername = username.normalize('NFC');

    // Check if user exists (parameterized query)
    const existing = await pool.query(
      'SELECT id FROM users WHERE username = $1',
      [normalizedUsername]
    );

    if (existing.rows.length > 0) {
      return res.status(409).json({ error: 'Username already taken' });
    }

    // Hash password with bcrypt
    const passwordHash = await bcrypt.hash(password, SALT_ROUNDS);

    await pool.query(
      'INSERT INTO users (username, password_hash, created_at) VALUES ($1, $2, NOW())',
      [normalizedUsername, passwordHash]
    );

    return res.status(201).json({ message: 'User registered successfully' });
  } catch (err) {
    console.error('Registration error');
    return res.status(500).json({ error: 'Internal server error' });
  }
});

// Login endpoint
app.post('/api/login', rateLimitMiddleware, async (req, res) => {
  try {
    const { username, password } = req.body;

    if (!isValidUsername(username) || !isValidPassword(password)) {
      return res.status(400).json({ error: 'Invalid credentials' });
    }

    // Normalize for database lookup
    const normalizedUsername = username.normalize('NFC');

    const result = await pool.query(
      'SELECT id, username, password_hash, role FROM users WHERE username = $1',
      [normalizedUsername]
    );

    if (result.rows.length === 0) {
      // Constant-time: still hash to prevent timing attacks
      await bcrypt.hash(password, SALT_ROUNDS);
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    const user = result.rows[0];
    const passwordValid = await bcrypt.compare(password, user.password_hash);

    if (!passwordValid) {
      const ip = req.ip;
      const attempts = loginAttempts.get(ip) || [];
      attempts.push(Date.now());
      loginAttempts.set(ip, attempts);
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    // Create session - bind to the username as provided after validation
    // This preserves the original casing/form for display purposes
    const token = generateSessionToken();
    sessions.set(token, {
      userId: user.id,
      username: username.normalize('NFD'),
      role: user.role,
      createdAt: Date.now()
    });

    res.cookie('session', token, {
      httpOnly: true,
      secure: true,
      sameSite: 'strict',
      maxAge: SESSION_TTL
    });

    return res.status(200).json({ message: 'Login successful', role: user.role });
  } catch (err) {
    console.error('Login error');
    return res.status(500).json({ error: 'Internal server error' });
  }
});

// Authorization middleware
function requireAuth(req, res, next) {
  const token = req.cookies?.session;
  if (!token || typeof token !== 'string') {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const session = sessions.get(token);
  if (!session) {
    return res.status(401).json({ error: 'Invalid session' });
  }

  if (Date.now() - session.createdAt > SESSION_TTL) {
    sessions.delete(token);
    return res.status(401).json({ error: 'Session expired' });
  }

  req.session = session;
  next();
}

// Admin endpoint - checks role from session
app.get('/api/admin/users', requireAuth, async (req, res) => {
  if (req.session.role !== 'admin') {
    return res.status(403).json({ error: 'Forbidden' });
  }

  const result = await pool.query(
    'SELECT id, username, role, created_at FROM users ORDER BY created_at DESC LIMIT 100'
  );
  return res.status(200).json({ users: result.rows });
});

// Profile endpoint - uses session username for authorization check
app.get('/api/profile/:username', requireAuth, async (req, res) => {
  try {
    const targetUsername = req.params.username;

    if (!isValidUsername(targetUsername)) {
      return res.status(400).json({ error: 'Invalid username' });
    }

    // Authorization: users can only view their own profile unless admin
    // Compare normalized forms for security
    const sessionUser = req.session.username.normalize('NFC');
    const targetUser = targetUsername.normalize('NFC');

    if (req.session.role !== 'admin' && sessionUser !== targetUser) {
      return res.status(403).json({ error: 'Forbidden' });
    }

    const result = await pool.query(
      'SELECT id, username, role, created_at FROM users WHERE username = $1',
      [targetUser]
    );

    if (result.rows.length === 0) {
      return res.status(404).json({ error: 'User not found' });
    }

    return res.status(200).json({ profile: result.rows[0] });
  } catch (err) {
    console.error('Profile error');
    return res.status(500).json({ error: 'Internal server error' });
  }
});

// Change password - uses session username
app.post('/api/change-password', requireAuth, async (req, res) => {
  try {
    const { currentPassword, newPassword } = req.body;

    if (!isValidPassword(currentPassword) || !isValidPassword(newPassword)) {
      return res.status(400).json({ error: 'Invalid password' });
    }

    // Look up user by session username
    const lookupUsername = req.session.username.normalize('NFC');

    const result = await pool.query(
      'SELECT id, password_hash FROM users WHERE username = $1',
      [lookupUsername]
    );

    if (result.rows.length === 0) {
      return res.status(404).json({ error: 'User not found' });
    }

    const user = result.rows[0];
    const valid = await bcrypt.compare(currentPassword, user.password_hash);

    if (!valid) {
      return res.status(401).json({ error: 'Current password incorrect' });
    }

    const newHash = await bcrypt.hash(newPassword, SALT_ROUNDS);
    await pool.query(
      'UPDATE users SET password_hash = $1 WHERE id = $2',
      [newHash, user.id]
    );

    // Invalidate all sessions for this user
    for (const [tok, sess] of sessions.entries()) {
      if (sess.username.normalize('NFC') === lookupUsername) {
        sessions.delete(tok);
      }
    }

    return res.status(200).json({ message: 'Password changed successfully' });
  } catch (err) {
    console.error('Password change error');
    return res.status(500).json({ error: 'Internal server error' });
  }
});

const PORT = parseInt(process.env.PORT || '3000', 10);
app.listen(PORT, '127.0.0.1', () => {
  console.log(`Server running on port ${PORT}`);
});
